 const c=$('#cv').getContext('2d');let sn=[{x:7,y:7},{x:6,y:7}],d={x:1,y:0},nd=d,f={x:11,y:7},sc=0;
 const dirs={ArrowLeft:[-1,0],ArrowRight:[1,0],ArrowUp:[0,-1],ArrowDown:[0,1]},bd={L:[-1,0],R:[1,0],U:[0,-1],D:[0,1]};
 const set=(x,y)=>{if(x!==-d.x||y!==-d.y)nd={x,y}};
