function clawGame(box){
 const P=['🧸','🐥','🎁','🚀','🦄','🪀'];let prizes=[],x=20,dir=1,y=40,ph='move',tries=6,sc=0,got=null;
 box.innerHTML='<p class="muted">Press DROP when the claw is above a prize. You have 6 tries!</p><canvas id="cv" width="360" height="300"></canvas><div class="row" style="justify-content:center"><span class="pill" id="cs">Prizes: 0 • Tries left: 6</span><button class="btn" id="cd">⬇ DROP</button></div><div id="gmsg"></div>';
 const c=$('#cv').getContext('2d');
 for(let i=0;i<7;i++)prizes.push({x:25+i*50,e:P[Math.floor(Math.random()*P.length)],ok:true});
 $('#cd').onclick=()=>{if(ph==='move')ph='drop'};
 const iv=setInterval(()=>{
  if(ph==='move'){x+=dir*3;if(x>340||x<20)dir*=-1}
  else if(ph==='drop'){y+=6;if(y>=230){const p=prizes.find(p=>p.ok&&Math.abs(p.x-x)<22);if(p){p.ok=false;got=p.e}ph='rise'}}
  else if(ph==='rise'){y-=6;if(y<=40){y=40;if(got){sc++;got=null}tries--;$('#cs').textContent='Prizes: '+sc+' • Tries left: '+tries;
   if(tries>0)ph='move';else{ph='end';clearInterval(iv);const nb=setHS('claw',sc);$('#gmsg').innerHTML='<div class="msg ok">You grabbed '+sc+' prize(s)!'+(nb&&sc?' NEW BEST! 🏆':'')+'</div><button class="btn" onclick="startGame(\'claw\')">Play again</button>'}}}
  c.clearRect(0,0,360,300);c.fillStyle='#2a3a9a';c.fillRect(0,38,360,3);c.fillRect(0,270,360,30);
  c.font='30px serif';c.textAlign='center';prizes.forEach(p=>{if(p.ok)c.fillText(p.e,p.x,262)});
  c.strokeStyle='#00d4ff';c.lineWidth=3;c.beginPath();c.moveTo(x,38);c.lineTo(x,y);c.stroke();c.beginPath();c.arc(x,y+6,13,0,Math.PI);c.stroke();
  if(got)c.fillText(got,x,y+34)},30);
 gameStop=()=>clearInterval(iv)}
function raceGame(box){
 box.innerHTML='<p class="muted">Steer with the ← → keys or the buttons. Dodge the cones! The longer you drive, the higher your score.</p><canvas id="cv" width="300" height="440"></canvas><div class="row" style="justify-content:center"><button class="btn alt" id="rl">⬅ Left</button><button class="btn alt" id="rr">Right ➡</button></div><div id="gmsg"></div>';
 const c=$('#cv').getContext('2d');let lane=1,obs=[],sc=0,sp=0,v=160,over=false,last=performance.now(),raf,off=0;
 const mv=d=>{lane=Math.max(0,Math.min(2,lane+d))};
 const kd=e=>{if(e.key==='ArrowLeft'){e.preventDefault();mv(-1)}if(e.key==='ArrowRight'){e.preventDefault();mv(1)}};
 document.addEventListener('keydown',kd);$('#rl').onclick=()=>mv(-1);$('#rr').onclick=()=>mv(1);
 gameStop=()=>{over=true;cancelAnimationFrame(raf);document.removeEventListener('keydown',kd)};
 function loop(now){if(over)return;const dt=Math.min((now-last)/1000,.05);last=now;sc+=dt*10;v+=dt*6;sp-=dt;off=(off+v*dt)%40;
  if(sp<=0){obs.push({l:Math.floor(Math.random()*3),y:-40});sp=Math.max(.45,1.1-sc/150)}
  obs.forEach(o=>o.y+=v*dt);obs=obs.filter(o=>o.y<470);
  c.clearRect(0,0,300,440);c.fillStyle='#2a3a9a';for(let y=-40+off;y<440;y+=40){c.fillRect(99,y,3,20);c.fillRect(199,y,3,20)}
  c.font='34px serif';c.textAlign='center';obs.forEach(o=>c.fillText('🚧',o.l*100+50,o.y+30));c.fillText('🏎️',lane*100+50,410);
  c.fillStyle='#e8ecff';c.font='bold 18px sans-serif';c.textAlign='left';c.fillText('Score '+Math.floor(sc),10,24);
  if(obs.some(o=>o.l===lane&&o.y>350&&o.y<410)){gameStop();const s=Math.floor(sc),nb=setHS('racing',s);$('#gmsg').innerHTML='<div class="msg bad">Crash! 🚧 Score: '+s+(nb?' – NEW BEST! 🏆':'')+'</div><button class="btn" onclick="startGame(\'racing\')">Play again</button>';return}
  raf=requestAnimationFrame(loop)}
 raf=requestAnimationFrame(loop)}
function bounceGame(box){
 box.innerHTML='<p class="muted">Move your mouse, finger or ← → keys to bounce the ball and break all the bricks. You have 3 lives!</p><canvas id="cv" width="360" height="420"></canvas><div id="gmsg"></div>';
 const cv=$('#cv'),c=cv.getContext('2d');let px=180,bx=180,by=300,vx=150,vy=-200,lives=3,sc=0,over=false,keys={},raf,last=performance.now();
 const br=[];for(let r=0;r<4;r++)for(let k=0;k<7;k++)br.push({x:8+k*49,y:50+r*24,ok:true});
 const mv=e=>{const r=cv.getBoundingClientRect();px=Math.max(40,Math.min(320,(e.clientX-r.left)*360/r.width))};
 cv.addEventListener('pointermove',mv);cv.addEventListener('pointerdown',mv);
 const kd=e=>{keys[e.key]=true;if(e.key.startsWith('Arrow'))e.preventDefault()},ku=e=>keys[e.key]=false;
 document.addEventListener('keydown',kd);document.addEventListener('keyup',ku);
 gameStop=()=>{over=true;cancelAnimationFrame(raf);document.removeEventListener('keydown',kd);document.removeEventListener('keyup',ku)};
 function finish(win){gameStop();const nb=setHS('bounce',sc);$('#gmsg').innerHTML='<div class="msg '+(win?'ok':'bad')+'">'+(win?'🎉 You cleared every brick!':'Game over!')+' Bricks: '+sc+(nb&&sc?' – NEW BEST! 🏆':'')+'</div><button class="btn" onclick="startGame(\'bounce\')">Play again</button>'}
 function loop(now){if(over)return;const dt=Math.min((now-last)/1000,.04);last=now;
  if(keys.ArrowLeft)px=Math.max(40,px-320*dt);if(keys.ArrowRight)px=Math.min(320,px+320*dt);
  bx+=vx*dt;by+=vy*dt;
  if(bx<8||bx>352){vx=-vx;bx=Math.max(8,Math.min(352,bx))}if(by<8){vy=Math.abs(vy);by=8}
  if(vy>0&&by>392&&by<408&&Math.abs(bx-px)<46){vy=-Math.abs(vy);vx=(bx-px)*5}
  for(const b of br){if(b.ok&&bx>b.x&&bx<b.x+45&&by>b.y&&by<b.y+20){b.ok=false;sc++;vy=-vy;break}}
  if(by>430){lives--;if(lives<=0){finish(false);return}bx=180;by=300;vx=150;vy=-200}
  if(sc===br.length){finish(true);return}
  c.clearRect(0,0,360,420);br.forEach((b,i)=>{if(b.ok){c.fillStyle=['#ff5c7a','#f5c542','#2ee59d','#00d4ff'][Math.floor(i/7)];c.fillRect(b.x,b.y,45,20)}});
  c.fillStyle='#a855f7';c.fillRect(px-40,400,80,12);c.fillStyle='#e8ecff';c.beginPath();c.arc(bx,by,7,0,7);c.fill();
  c.font='bold 16px sans-serif';c.textAlign='left';c.fillText('Bricks '+sc+'   ❤️ '+lives,10,24);
  raf=requestAnimationFrame(loop)}
 raf=requestAnimationFrame(loop)}

/* ---------- TEACHER ---------- */
function create(){
 return `<h1>➕ Create a Quiz</h1><div class="card"><p class="muted">Demo: quizzes are saved only in this browser. Add one or more questions, then save.</p>
 <label>Quiz title</label><input id="t-title" maxlength="60" placeholder="e.g. Fractions Fun">
 <div class="two"><div><label>Subject</label><select id="t-subj">${SUBJ.map(s=>`<option>${s}</option>`).join('')}</select></div>
 <div><label>Coins per correct answer (1–50)</label><input id="t-rew" type="number" min="1" max="50" value="5"></div></div>
 <label>Time limit in minutes (optional, leave blank for none)</label><input id="t-time" type="number" min="1" max="120" placeholder="No limit">
 <hr style="border-color:#2a3a9a"><h3>Question</h3><textarea id="t-q" rows="2" maxlength="200" placeholder="Type the question"></textarea>
 <div class="two">${[0,1,2,3].map(k=>`<div><label>Option ${'ABCD'[k]}</label><input id="t-o${k}" maxlength="80"></div>`).join('')}</div>
 <label>Correct answer</label><select id="t-ans"><option value="0">A</option><option value="1">B</option><option value="2">C</option><option value="3">D</option></select>
 <div id="t-err"></div><div id="t-draft"></div>
 <button class="btn alt" onclick="addQ()">➕ Add question to quiz</button> <button class="btn" onclick="saveQuiz()">💾 Save quiz</button></div>`}
function terr(m){$('#t-err').innerHTML=m?'<div class="msg bad">'+esc(m)+'</div>':''}
function showDraft(){$('#t-draft').innerHTML=draft.length?'<h3>Questions in this quiz ('+draft.length+')</h3>'+draft.map((q,i)=>`<p>${i+1}. ${esc(q.q)} <button class="btn red" style="padding:4px 10px" onclick="draft.splice(${i},1);showDraft()">Remove</button></p>`).join(''):'<p class="muted">No questions added yet.</p>'}
function addQ(){
 const q=$('#t-q').value.trim(),o=[0,1,2,3].map(k=>$('#t-o'+k).value.trim());
 if(q.length<5){terr('Please type a question (at least 5 characters).');return false}
 if(o.some(x=>!x)){terr('Please fill in all four answer options.');return false}
 if(new Set(o.map(x=>x.toLowerCase())).size<4){terr('Each answer option should be different.');return false}
 draft.push({q,o,a:+$('#t-ans').value});
 ['t-q','t-o0','t-o1','t-o2','t-o3'].forEach(id=>$('#'+id).value='');$('#t-ans').value='0';terr('');showDraft();toast('Question added ✅');return true}
function saveQuiz(){
 const title=$('#t-title').value.trim(),rew=Number($('#t-rew').value),tv=$('#t-time').value.trim();
 if(title.length<3){terr('Please give the quiz a title (at least 3 characters).');return}
 if(!Number.isInteger(rew)||rew<1||rew>50){terr('Coin reward must be a whole number from 1 to 50.');return}
 let time=0;if(tv!==''){time=Number(tv);if(!Number.isInteger(time)||time<1||time>120){terr('Time limit must be a whole number from 1 to 120 minutes, or blank.');return}}
 const started=['t-q','t-o0','t-o1','t-o2','t-o3'].some(id=>$('#'+id).value.trim());
 if(started&&!addQ())return;
 if(!draft.length){terr('Add at least one question before saving.');return}
 S.custom.push({id:'c'+Date.now(),title,subject:$('#t-subj').value,reward:rew,time,qs:draft.slice(),custom:true});
 draft=[];save();toast('Quiz saved! Students can play it from Quizzes (same browser only). 🎉');go('tquizzes')}
function tquizzes(){
 const rows=allQ();
 return `<h1>📚 My Quizzes</h1><p class="muted">Sample quizzes plus quizzes created in this browser. Teacher view shows correct answers.</p>
 <div class="grid">${rows.map(q=>`<div class="card" style="--c:${SC[q.subject]}"><div class="muted">${ICON[q.subject]} ${q.subject} ${q.custom?'• created by you':'• sample'}</div><h3>${esc(q.title)}</h3><p>${q.qs.length} question(s)</p><p>${qMeta(q)}</p>
 <details><summary>View questions</summary>${q.qs.map((x,i)=>`<p><b>${i+1}. ${esc(x.q)}</b><br>${x.o.map((o,k)=>(k===x.a?'✅ ':'▫️ ')+esc(o)).join('<br>')}</p>`).join('')}</details>
 ${q.custom?`<button class="btn red" onclick="delQuiz('${q.id}')">Delete</button>`:''}</div>`).join('')}</div>
 ${S.custom.length?'':'<div class="empty" style="margin-top:16px">You have not created any quizzes yet. Use “Create Quiz” to make your first one! ✏️</div>'}`}
function delQuiz(id){if(!confirm('Delete this quiz and its saved results?'))return;S.custom=S.custom.filter(q=>q.id!==id);delete S.results[id];save();draw();toast('Quiz deleted.')}
function results(){
 const list=allQ().filter(q=>S.results[q.id]);
 return `<h1>🧾 Class Results (this browser only)</h1><p class="muted">Demo: shows the one demo student in this browser. Data is not secure and can be edited by anyone using this browser.</p>
 ${list.length?list.map(q=>{const r=S.results[q.id];
 return `<details><summary>${ICON[q.subject]} ${esc(q.title)} — ${r.score}/${r.total} • ${r.attempts} attempt(s)</summary><p class="muted">Last attempt: ${esc(r.date)} • Coins earned: ${r.coins}</p>
 ${q.qs.map((x,i)=>{const a=r.answers[i]||{};return `<div class="card" style="margin:8px 0"><b>${i+1}. ${esc(x.q)}</b><br>Student answered: ${a.sel==null?'<i>(no answer)</i>':esc(x.o[a.sel])} ${a.ok?'✅':'❌'}<br><span class="muted">Correct: ${esc(x.o[x.a])}</span>
 ${q.subject==='Mathematics'?`<br>✍️ Working: ${a.work?esc(a.work):'<i>(none written)</i>'}`:''}</div>`}).join('')}</details>`}).join('')
 :'<div class="empty">No results yet. Switch to Student, finish a quiz, then come back here. 📭</div>'}`}
function classView(){
 return `<h1>🔑 Classroom Code</h1><div class="card" style="text-align:center"><div class="muted">Sample code</div><div class="code" id="cc">${CODE}</div><button class="btn" onclick="copyCode()">📋 Copy code</button>
 <div class="msg bad" style="margin-top:16px">⚠️ Demo only: this code does NOT connect different computers. Nothing syncs online, and each browser keeps its own separate data.</div></div>`}
function copyCode(){
 const fb=()=>{const t=document.createElement('textarea');t.value=CODE;document.body.appendChild(t);t.select();let ok=false;try{ok=document.execCommand('copy')}catch(e){}t.remove();toast(ok?'Code copied! 📋':'Copy failed. Please select the code and copy it manually.',ok?'ok':'bad')};
 if(navigator.clipboard&&navigator.clipboard.writeText)navigator.clipboard.writeText(CODE).then(()=>toast('Code copied! 📋')).catch(fb);else fb()}

render();
